// Build the "team progression" dataset: the Stevens team's best mark in every
// event x gender x season, one row per year the event was contested.
//   node scripts/gen-progression.mjs
// Produces:
//   public/progression.json   { "<eventId>|<gender>|<season>": YearBest[] }
//   YearBest = { y: year, m: mark, id: athlete_id, n: name, d: date,
//                l: result_link, r: all-time rank | null }
//
// Fetched once by /events/progression and cached by the service worker — kept
// out of the JS bundle. Regenerated by `npm run data` and as a prebuild step.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (p) => JSON.parse(readFileSync(join(root, p), "utf8"));

const athletes = read("data/athletes.json");
const performances = read("data/performances.json");
const events = read("data/events.json");
const topTen = read("data/top10.json");

const athById = new Map(athletes.map((a) => [a.athlete_id, a]));
const hibById = new Map(events.map((e) => [e.event_id, e.higher_is_better]));

const seasonYearOf = (d) => d.getFullYear() + (d.getMonth() >= 11 ? 1 : 0);

// all-time team-list rank (mirrors lib/data.ts teamRank)
const topIdx = new Map();
for (const l of topTen) {
  if (l.event_id != null && !l.relay) {
    topIdx.set(`${l.event_id}|${l.gender}|${l.season}`, l);
  }
}
const topRank = (athleteId, eventId, season, gender) => {
  const list = topIdx.get(`${eventId}|${gender}|${season}`);
  const e = list?.entries.find((x) => x.athlete_id === athleteId);
  return e ? e.rank : null;
};

// key -> year -> that year's best row
const groups = new Map();

for (const p of performances) {
  const a = athById.get(p.athlete_id);
  if (!a || !a.sex) continue;
  const gender = a.sex.toLowerCase();
  const season = p.season === "i" ? "indoor" : "outdoor";
  const key = `${p.event_id}|${gender}|${season}`;
  const year = seasonYearOf(new Date(`${p.date}T00:00:00`));
  const hib = hibById.get(p.event_id) ?? false;

  let byYear = groups.get(key);
  if (!byYear) groups.set(key, (byYear = new Map()));
  const cur = byYear.get(year);
  if (cur && (hib ? cur.m >= p.mark : cur.m <= p.mark)) continue;
  byYear.set(year, {
    y: year,
    m: p.mark,
    id: p.athlete_id,
    n: `${a.nickname || a.first_name} ${a.last_name}`,
    d: p.date,
    l: p.result_link,
    r: null,
  });
}

const out = {};
for (const [key, byYear] of groups) {
  const [eventId, gender, season] = key.split("|");
  const rows = [...byYear.values()].sort((a, b) => a.y - b.y);
  for (const row of rows) row.r = topRank(row.id, Number(eventId), season, gender);
  out[key] = rows;
}

writeFileSync(
  join(root, "public", "progression.json"),
  JSON.stringify(out) + "\n"
);

const bytes = readFileSync(join(root, "public", "progression.json")).length;
console.log(
  `wrote public/progression.json (${Object.keys(out).length} event/gender/season combos, ${(bytes / 1024).toFixed(0)} KB)`
);
